<?php

namespace CM3_Lib\util;

use CM3_Lib\database\Column;

/**
 * Helpers for exporting entity data.
 * Identifies columns that should be excluded from exports (auto-generated, computed,
 * auto-incrementing) and encodes binary column values for safe JSON transport.
 */
class ExportHelpers
{
    /**
     * Column names that are auto-generated by the database and should be
     * excluded from export data. These have database defaults (CURRENT_TIMESTAMP)
     * and carry no meaningful application data.
     *
     * @var string[]
     */
    private static array $autoGeneratedColumns = [
        'date_created',
        'date_modified',
    ];

    /**
     * Column names that are auto-incrementing primary keys and should be
     * excluded from child-entity exports. When entities are nested hierarchically
     * under their parent, the child's database ID is redundant — the import
     * assigns fresh IDs and the hierarchy itself encodes the relationship.
     *
     * Only top-level entities (groups) need their IDs for stable matching.
     *
     * @var string[]
     */
    private static array $autoIncrementColumns = [
        'id',
    ];

    /**
     * Return the list of column names that should be excluded from export results.
     * Combines auto-generated columns with computed/generated columns and
     * auto-incrementing primary keys from the schema.
     *
     * @param array<string, Column> $columnDefs The ColumnDefs from a Table model.
     * @param bool $isTopLevel Whether this entity is top-level (groups). If false,
     *                         auto-incrementing IDs are also excluded.
     * @return string[] Column names to exclude.
     */
    public static function getExcludedExportColumns(array $columnDefs, bool $isTopLevel = false): array
    {
        // Start with always-excluded columns
        $excluded = self::$autoGeneratedColumns;

        // Exclude auto-incrementing IDs from child entities (nests under groups)
        if (!$isTopLevel) {
            $excluded = array_merge($excluded, self::$autoIncrementColumns);
        }

        // Add computed/generated columns detected from Column definitions
        foreach ($columnDefs as $name => $col) {
            if (self::isComputedColumn($col)) {
                $excluded[] = $name;
            }
        }

        return array_unique($excluded);
    }

    /**
     * Check if a Column definition represents a computed/generated column.
     * Computed columns have a customPostfix containing "GENERATED ALWAYS".
     *
     * @param Column $col The column definition to check.
     * @return true if the column is computed/generated, false otherwise.
     */
    public static function isComputedColumn(Column $col): bool
    {
        if ($col->customPostfix === null) {
            return false;
        }
        return stripos($col->customPostfix, 'GENERATED ALWAYS') !== false;
    }

    /**
     * Strip auto-generated, computed, and (for child entities) auto-incrementing
     * columns from an array of rows.
     *
     * @param array<array<string, mixed>> $rows The rows returned from Search().
     * @param array<string, Column> $columnDefs The ColumnDefs from the table model.
     * @param bool $isTopLevel Whether this entity is top-level (groups).
     * @return array<array<string, mixed>> Cleaned rows.
     */
    public static function stripExportColumns(array $rows, array $columnDefs, bool $isTopLevel = false): array
    {
        if (empty($rows)) {
            return $rows;
        }

        $excluded = self::getExcludedExportColumns($columnDefs, $isTopLevel);

        return array_map(function ($row) use ($excluded) {
            foreach ($excluded as $col) {
                unset($row[$col]);
            }
            return $row;
        }, $rows);
    }

    /**
     * Encode binary column values for safe JSON transport.
     * Binary columns (BINARY, BLOB types) are converted to base64-encoded strings
     * with a "_encoded" suffix so consumers know they need decoding.
     *
     * @param array<string, mixed> $record A single row of data.
     * @param array<string, Column> $columnDefs The ColumnDefs from the table model.
     * @return array<string, mixed> Record with encoded binary values.
     */
    public static function encodeBinaryColumns(array $record, array $columnDefs): array
    {
        foreach ($record as $colName => $value) {
            if (!isset($columnDefs[$colName])) {
                continue;
            }
            $col = $columnDefs[$colName];
            if (self::isBinaryColumn($col)) {
                if ($value !== null && $value !== '') {
                    $record[$colName . '_encoded'] = base64_encode((string)$value);
                    unset($record[$colName]);
                } else {
                    unset($record[$colName]);
                }
            }
        }
        return $record;
    }

    /**
     * Check if a Column definition represents a binary type (BINARY, BLOB).
     * Note: TEXT types are treated as strings by PDO/MySQLi and don't need encoding.
     *
     * @param Column $col The column definition to check.
     * @return true if the column is binary, false otherwise.
     */
    public static function isBinaryColumn(Column $col): bool
    {
        $type = strtoupper($col->dbType);
        if (strpos($type, 'BLOB') !== false) {
            return true;
        }
        // BINARY(n) is a fixed-length binary string (not VARBINARY)
        if ($type === 'BINARY') {
            return true;
        }
        return false;
    }
}
